generate.initial_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?totalHoldingGain ?netCashFlow ?riskPressureScore WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:hasPortfolioHealth ?ph .
  ?ph wm:riskScore ?riskScore ;
      wm:liquidityScore ?liquidityScore ;
      wm:diversificationScore ?diversificationScore .

  {
    SELECT ?inv (SUM(xsd:decimal(?gain)) AS ?totalHoldingGain) WHERE {
      ?inv wm:hasHolding ?hold .
      ?hold wm:currentValue ?cv ;
            wm:cost ?cost .
      BIND (xsd:decimal(?cv) - xsd:decimal(?cost) AS ?gain)
    } GROUP BY ?inv
  }

  {
    SELECT ?inv (SUM(xsd:decimal(?amount)) AS ?netCashFlow) WHERE {
      ?inv wm:hasCashFlow ?cf .
      ?cf wm:amount ?amount .
    } GROUP BY ?inv
  }

  BIND ( xsd:decimal(?riskScore) + (100.0 - xsd:decimal(?liquidityScore)) + (100.0 - xsd:decimal(?diversificationScore)) AS ?riskPressureScore)

  FILTER ( ?totalHoldingGain < 0 )
  FILTER ( ?netCashFlow < 0 )
  FILTER ( ?riskPressureScore > 180 )
}

